    public TileGridManager tileGridManager;

    private void Update()
    {
        if (Input.GetMouseButtonDown(0))
        {
            Ray ray = Camera.main.ScreenPointToRay(Input.mousePosition);
            RaycastHit hit;
            if (Physics2D.Raycast(ray.origin, ray.direction, 1000f, LayerMask.GetMask("TileGrid")))
            {
                GameObject tile = hit.collider.gameObject;
                int x = tile.name.Split('_')[1].ToInt();
                int y = tile.name.Split('_')[2].ToInt();
                // Mover el tile hacia arriba
                for (int i = y - 1; i >= 0; i--)
                {
                    GameObject tileAbove = tileGridManager.tiles[x, i];
                    tileAbove.transform.position += new Vector3(0, 1f, 0);
                    tile.transform.position -= new Vector3(0, 1f, 0);
                    break;
                }
            }
        }
    }
}
