class Program
{
    static void Main(string[] args)
    {
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://localhost:8080/hello");

        listener.Start();

        Console.WriteLine("Serveur HTTP démarré");
        Console.WriteLine("Tapez 'q' pour quitter");

        while (true)
        {
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;

            if (request.Url.AbsolutePath == "/hello")
            {
                HttpResponse response = context.Response;
                byte[] buffer = System.Text.Encoding.UTF8.GetBytes("Hello");
                response.OutputStream.Write(buffer, 0, buffer.Length);
                response.OutputStream.Close();
            }
            else
            {
                // Traiter les autres requêtes
                response.StatusDescription = "501 Not Implemented";
            }
        }
    }
}
```
