  // тело теста 2
});

it('test3', () => {
  // тело теста 3
});
```
В этом случае тест `test1` будет выполняться перед тестом `test2`.

3. Используя метод `describe()` и параметр `sequence`:
```
describe('Test Suite', () => {
  it('test1', () => {
    // тело теста 1
  }).sequence('test2');

  it('test2', () => {
    // тело теста 2
  });

  it('test3', () => {
    // тело теста 3
  });
});
```
В этом случае тесты в блоке `describe` будут выполняться в порядке, в котором они были определены.

