      .catch((error) => {
        console.error(error);
      });
  };

  handleGoogleSignOut = () => {
    signOut(auth)
      .then(() => {
        this.setState({ user: null, authenticated: false });
      })
      .catch((error) => {
        console.error(error);
      });
  };

  render() {
    return (
      <Card>
        <CardContent>
          <Typography variant="h5" component="h2">
            Session Management
