                ${button ? `${button}` : ''}
            </div>
        `);
        snackbarWrapper.insertAdjacentHTML('beforeend', template);
        snackbar = document.getElementById(`snackbar_message_${num}`);
    }

    setTimeout(function() {
        snackbar.style.cssText = "opacity: 1; transform: translateY(0%); transition: opacity 200ms ease-in, transform 200ms cubic-bezier(0.175, 0.885, 0.32, 1.275);";
